// Gallery for comparing brand explorations. Reads manifest.json
// (generated by scripts/build-manifest.mjs). Favourites live in localStorage.

const $ = s => document.querySelector(s)
const store = {
  get(k, d) { try { return JSON.parse(localStorage.getItem(k)) ?? d } catch { return d } },
  set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)) } catch {} },
}

const designs = await fetch('manifest.json').then(r => r.json()).catch(() => [])
let favs = new Set(store.get('favs', []))
let round = store.get('round', ''), favOnly = false, compare = false, showInfo = true
let current = designs.findIndex(d => d.id === location.hash.slice(1))
if (current < 0) current = 0
let second = null // index shown on the right in compare mode

const visible = () => designs.map((d, i) => i).filter(i => (!favOnly || favs.has(designs[i].id)) && (!round || String(designs[i].round) === round))

function renderList() {
  const list = $('#list')
  list.innerHTML = ''
  for (const i of visible()) {
    const d = designs[i]
    const li = document.createElement('li')
    li.innerHTML = `<a href="#${d.id}" aria-current="${i === current}">
      <span class="n">${d.id}</span><span class="name"></span>
      <button class="star" aria-pressed="${favs.has(d.id)}" aria-label="Favourite">★</button>
      <span class="tag"></span><span class="sw">${(d.palette || []).slice(0, 6).map(c => `<i style="background:${c}"></i>`).join('')}</span></a>`
    li.querySelector('.name').textContent = d.name || 'Untitled'
    li.querySelector('.tag').textContent = d.tagline || ''
    li.querySelector('a').addEventListener('click', e => {
      if (e.target.closest('.star')) { e.preventDefault(); toggleFav(d.id); return }
      e.preventDefault()
      if (compare && (e.metaKey || e.shiftKey)) second = i; else current = i
      update()
    })
    list.append(li)
  }
  $('#count').textContent = `· ${designs.length} designs · ${favs.size} favourites`
}

function frame(d) {
  const vp = $('#vp').value
  const el = document.createElement('div')
  el.className = 'frame'
  if (vp) el.style.setProperty('--w', vp + 'px')
  el.innerHTML = `<div class="cap"><span><b></b></span><span><a class="as" target="_blank" rel="noopener" hidden>Assets ↗</a> <a class="op" target="_blank" rel="noopener">Open ↗</a></span></div><iframe loading="eager"></iframe>`
  el.querySelector('b').textContent = `${d.id} · ${d.name || ''}`
  el.querySelector('.op').href = d.path
  if (d.assets) { const a = el.querySelector('.as'); a.href = d.assets; a.hidden = false }
  el.querySelector('iframe').src = d.path
  el.querySelector('iframe').title = d.name || d.id
  return el
}

function renderStage() {
  const stage = $('#stage')
  stage.innerHTML = ''
  if (!designs.length) { stage.innerHTML = '<p class="empty">No designs yet. Run <code>node scripts/build-manifest.mjs</code>.</p>'; return }
  stage.append(frame(designs[current]))
  if (compare) {
    if (second == null || second === current) second = (current + 1) % designs.length
    stage.append(frame(designs[second]))
  }
}

function renderInfo() {
  const info = $('#info'), d = designs[current]
  info.hidden = !showInfo || !d
  if (!d) return
  info.innerHTML = ''
  for (const [k, label] of [['summary', 'Vision'], ['voice', 'Voice'], ['type', 'Type'], ['motion', 'Motion'], ['sound', 'Sound'], ['mark', 'Mark'], ['inspiration', 'Inspiration']]) {
    let v = d[k]; if (!v) continue
    if (Array.isArray(v)) v = v.join(', ')
    const dt = document.createElement('dt'); dt.textContent = label
    const dd = document.createElement('dd'); dd.textContent = v
    const wrap = document.createElement('div'); wrap.append(dt, dd); info.append(wrap)
  }
}

function update() {
  history.replaceState(null, '', '#' + (designs[current]?.id ?? ''))
  renderList(); renderStage(); renderInfo()
}

function toggleFav(id) {
  favs.has(id) ? favs.delete(id) : favs.add(id)
  store.set('favs', [...favs]); renderList()
}

function step(dir) {
  const v = visible(); if (!v.length) return
  const pos = v.indexOf(current)
  current = v[(pos + dir + v.length) % v.length]
  update()
}

$('#vp').addEventListener('change', () => { store.set('vp', $('#vp').value); renderStage() })
$('#vp').value = store.get('vp', '')
$('#round').value = round
$('#round').addEventListener('change', e => { round = e.target.value; store.set('round', round); const v = visible(); if (v.length && !v.includes(current)) current = v[0]; update() })
$('#favOnly').addEventListener('click', e => { favOnly = !favOnly; e.currentTarget.setAttribute('aria-pressed', favOnly); if (favOnly && !favs.has(designs[current]?.id)) { const v = visible(); if (v.length) current = v[0] } update() })
$('#compare').addEventListener('click', e => { compare = !compare; e.currentTarget.setAttribute('aria-pressed', compare); renderStage() })
$('#infoBtn').addEventListener('click', e => { showInfo = !showInfo; e.currentTarget.setAttribute('aria-pressed', showInfo); renderInfo() })
$('#copy').addEventListener('click', async e => {
  const picks = designs.filter(d => favs.has(d.id)).map(d => `${d.id} ${d.name}`).join('\n') || 'No favourites yet'
  try { await navigator.clipboard.writeText(`Favourite brand explorations:\n${picks}`); e.target.textContent = 'Copied' } catch { prompt('Copy:', picks) }
  setTimeout(() => (e.target.textContent = 'Copy picks'), 1500)
})
addEventListener('keydown', e => {
  if (e.target.matches('input, select, textarea')) return
  if (e.key === 'ArrowRight' || e.key === 'j') step(1)
  else if (e.key === 'ArrowLeft' || e.key === 'k') step(-1)
  else if (e.key === 'f') toggleFav(designs[current].id)
  else if (e.key === 'c') $('#compare').click()
  else if (e.key === 'i') $('#infoBtn').click()
})
addEventListener('hashchange', () => { const i = designs.findIndex(d => d.id === location.hash.slice(1)); if (i >= 0 && i !== current) { current = i; update() } })

update()
